    """业务日 D → 海豚 schedule [D+1 04:50, D+2 04:50)。"""
    sched_start = datetime.combine(start + timedelta(days=1), datetime.strptime("04:50:00", "%H:%M:%S").time())
    sched_end = datetime.combine(end + timedelta(days=2), datetime.strptime("04:50:00", "%H:%M:%S").time())
